function parseAmberLimit(value, fallback = 1) {
  const parsed = Number(value);
  return parsed || fallback;
}

module.exports = { parseAmberLimit };

const assert = require('node:assert/strict');
const { parseAmberLimit } = require('../src/amberHarness.js');

assert.equal(parseAmberLimit(' 12 '), 12);
assert.equal(parseAmberLimit('0'), 0);
assert.equal(parseAmberLimit('bad', 4), 4);

#!/usr/bin/env bash
set -euo pipefail
node test/amberHarness.test.js

